// ---------------------------------------------------------------------------
// Go helpers used by the admin templates

func csrfValue() string { return csrfToken }

func postFormAction(isNew bool) string {
	if isNew {
		return "/admin/posts/new"
	}
	return "/admin/posts/save"
}

func postID(p *store.Post) string {
	if p == nil {
		return "0"
	}
	return itoa64(p.ID)
}

func postTitle(p *store.Post) string {
	if p == nil {
		return ""
	}
	return p.Title
}

func postSlug(p *store.Post) string {
	if p == nil {
		return ""
	}
	return p.Slug
}

func postSummary(p *store.Post) string {
	if p == nil {
		return ""
	}
	return p.Summary
}

func postTags(p *store.Post) string {
	if p == nil {
		return ""
	}
	return strings.Join(p.Tags, ", ")
}

func postBody(p *store.Post) string {
	if p == nil {
		return ""
	}
	return p.Body
}

func postPublished(p *store.Post) bool {
	return p != nil && p.Published
}

// aiJobTitle shows the most descriptive label for an AI run: the final
// title, else the requested topic, else a placeholder.
func aiJobTitle(j store.AIGenJob) string {
	if t := strings.TrimSpace(j.Title); t != "" {
		return t
	}
	if t := strings.TrimSpace(j.TopicHint); t != "" {
		return t
	}
	return "(no topic)"
}

// aiStatusChip maps a run status to a colored chip class for the dashboard.
func aiStatusChip(status string) string {
	switch status {
	case "published", "done":
		return "chip ai-chip-ok"
	case "failed":
		return "chip ai-chip-err"
	default: // queued, planning, writing, publishing
		return "chip ai-chip-run"
	}
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func visibleLabel(visible bool) string {
	if visible {
		return "Hide"
	}
	return "Show"
}

func featuredLabel(featured bool) string {
	if featured {
		return "Unfeature"
	}
	return "Feature"
}

func shortDate(iso string) string {
	if len(iso) >= 10 {
		return iso[:10]
	}
	return iso
}

func itoa64(n int64) string {
	return itoa(int(n))
}

func fmtCount(n int64) string {
	if n < 1000 {
		return itoa64(n)
	}
	return itoa64(n/1000) + "k"
}

// csrfToken is set by the handler package at startup; it is rendered into
// every admin form as a hidden field and validated by the server.
var csrfToken = ""

// SetCSRFToken is called once at startup with a random token.
func SetCSRFToken(t string) { csrfToken = t }

func parentDir(rel string) string {
	d := filepath.Dir(rel)
	if d == "." || d == "/" || d == "\\" {
		return ""
	}
	return d
}

func projectVal(p *store.Project, key string) string {
	if p == nil {
		return ""
	}
	switch key {
	case "name":
		return p.Name
	case "slug":
		return p.Slug
	case "tagline":
		return p.Tagline
	case "summary":
		return p.Summary
	case "description":
		return p.Description
	case "language":
		return p.Language
	case "year":
		return p.Year
	case "repo_url":
		return p.RepoURL
	case "classification":
		return string(p.Classification)
	}
	return ""
}

func projectStackVal(p *store.Project) string {
	if p == nil {
		return ""
	}
	return strings.Join(p.Stack, ", ")
}

func projectFeaturesVal(p *store.Project) string {
	if p == nil {
		return ""
	}
	return strings.Join(p.Features, "\n")
}

func projectBool(p *store.Project, key string) bool {
	if p == nil {
		if key == "visible" {
			return true
		}
		return false
	}
	if key == "visible" {
		return p.Visible
	}
	if key == "featured" {
		return p.Featured
	}
	return false
}

var _ = templruntime.GeneratedTemplate
